<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use App\Services\Earnings;
class EarningsController extends Controller {
 public function summary(){
  $id=auth('app_users')->user()->id;$account=DB::table('earner_accounts')->where('user_id',$id)->first();
  $balances=[];foreach(DB::table('currencies')->where('enabled',true)->get() as $c)$balances[]=['currency_code'=>$c->code,'decimals'=>$c->decimals,'available_minor'=>(int)Earnings::eligible($id,$c->code)->sum('net_minor')+(int)Earnings::gifts($id,$c->code)->sum('net_minor'),'pending_minor'=>(int)DB::table('creator_sales')->where('creator_id',$id)->where('currency_code',$c->code)->where('status','pending_payout')->sum('gross_minor')+(int)DB::table('gift_cash_earnings')->where('creator_id',$id)->where('currency_code',$c->code)->where('status','pending_payout')->sum('gross_minor')];
  return response()->json(['status'=>true,'data'=>['withdrawals_enabled'=>(bool)DB::table('earning_policy')->where('id',1)->value('withdrawals_enabled'),'earner_status'=>$account?->status??'not_requested','balances'=>$balances,'withdrawals'=>DB::table('earning_withdrawals')->where('user_id',$id)->orderByDesc('created_at')->limit(100)->get(['id','currency_code','amount_minor','method','status','review_note','payment_reference','created_at','paid_at']),'message'=>'Cash earnings require settled sales, a seven-day hold and admin release. Only funded gifts create cash earnings at the admin-set share. Test, free and previously rewarded coins and venue quotes are excluded.']]);
 }
 public function apply(Request $r){$v=$r->validate(['note'=>'required|string|min:10|max:500']);$id=auth('app_users')->user()->id;return DB::transaction(function()use($id,$v){DB::table('users')->where('id',$id)->lockForUpdate()->first();$old=DB::table('earner_accounts')->where('user_id',$id)->first();if(!$old)DB::table('earner_accounts')->insert(['user_id'=>$id,'status'=>'pending','note'=>$v['note'],'created_at'=>now(),'updated_at'=>now()]);return $this->summary();});}
 public function request(Request $r){$v=$r->validate(['expected_amount_minor'=>'required|integer|min:1','request_key'=>'required|uuid','currency_code'=>'required|exists:currencies,code','method'=>'required|in:mobile_money,bank','destination'=>'required|string|min:5|max:500']);$me=auth('app_users')->user();
  return DB::transaction(function()use($v,$me){$user=DB::table('users')->where('id',$me->id)->lockForUpdate()->first();$old=DB::table('earning_withdrawals')->where('user_id',$me->id)->where('request_key',$v['request_key'])->first();if($old){if($old->currency_code!==$v['currency_code']||$old->method!==$v['method']||Crypt::decryptString($old->destination)!==$v['destination'])return response()->json(['status'=>false,'message'=>'Request key already used.'],409);return response()->json(['status'=>true,'id'=>$old->id,'message'=>'Request already received.']);}
   if(!DB::table('earning_policy')->where('id',1)->value('withdrawals_enabled'))return response()->json(['status'=>false,'message'=>'Withdrawals are awaiting administrator payout setup.'],409);if($user->is_block||$user->qa_coin_mode||DB::table('earner_accounts')->where('user_id',$me->id)->value('status')!=='approved')return response()->json(['status'=>false,'message'=>'An approved earning account is required. Test coin accounts cannot withdraw.'],403);
   if(!DB::table('currencies')->where('code',$v['currency_code'])->where('enabled',true)->exists())return response()->json(['status'=>false,'message'=>'Currency unavailable.'],409);
   $sales=Earnings::eligible($me->id,$v['currency_code'])->orderBy('id')->lockForUpdate()->get();$gifts=Earnings::gifts($me->id,$v['currency_code'])->orderBy('id')->lockForUpdate()->get();$amount=(int)$sales->sum('net_minor')+(int)$gifts->sum('net_minor');if($amount!== (int)$v['expected_amount_minor'])return response()->json(['status'=>false,'message'=>'Available earnings changed. Refresh and review the amount.'],409);if($amount<=0)return response()->json(['status'=>false,'message'=>'No released cash earnings are available.'],409);
   $id=(string)Str::uuid();DB::table('earning_withdrawals')->insert(['id'=>$id,'user_id'=>$me->id,'request_key'=>$v['request_key'],'currency_code'=>$v['currency_code'],'amount_minor'=>$amount,'method'=>$v['method'],'destination'=>Crypt::encryptString($v['destination']),'created_at'=>now(),'updated_at'=>now()]);DB::table('creator_sales')->whereIn('id',$sales->pluck('id'))->update(['status'=>'reserved','withdrawal_id'=>$id,'updated_at'=>now()]);DB::table('gift_cash_earnings')->whereIn('id',$gifts->pluck('id'))->update(['status'=>'reserved','withdrawal_id'=>$id,'updated_at'=>now()]);Earnings::event($id,'requested','user:'.$me->id);return response()->json(['status'=>true,'id'=>$id,'message'=>'Withdrawal requested. No payment has been sent.']);
  });
 }
 public function admin(){return view('earnings',['policy'=>DB::table('earning_policy')->where('id',1)->first(),'giftSales'=>DB::table('gift_cash_earnings')->orderByDesc('id')->limit(200)->get(),'accounts'=>DB::table('earner_accounts')->orderByDesc('updated_at')->limit(200)->get(),'sales'=>DB::table('creator_sales')->orderByDesc('id')->limit(200)->get(),'withdrawals'=>DB::table('earning_withdrawals')->orderByDesc('created_at')->limit(200)->get()]);}
 public function account(Request $r){$v=$r->validate(['user_id'=>'required|integer|exists:users,id','status'=>'required|in:approved,suspended','note'=>'required|string|max:500']);DB::transaction(function()use($v){$old=DB::table('earner_accounts')->where('user_id',$v['user_id'])->value('status');DB::table('earner_accounts')->updateOrInsert(['user_id'=>$v['user_id']],['status'=>$v['status'],'note'=>$v['note'],'updated_at'=>now()]);if($old!==$v['status'])Earnings::notify($v['user_id'],'Your earning account is '.$v['status'].'. '.$v['note']);});return back()->with('success','Earning account updated.');}
 public function policy(Request $r){$v=$r->validate(['gift_creator_bps'=>'required|integer|min:0|max:10000','content_creator_bps'=>'required|integer|min:0|max:10000','withdrawals_enabled'=>'required|boolean']);DB::table('earning_policy')->where('id',1)->update($v+['updated_at'=>now()]);return back()->with('success','Payout policy saved. Shares use basis points: 10000 = 100%.');}
 public function release(Request $r){$v=$r->validate(['sale_id'=>'required|integer','kind'=>'required|in:gift,content']);return DB::transaction(function()use($v){$table=$v['kind']==='gift'?'gift_cash_earnings':'creator_sales';$s=DB::table($table)->where('id',$v['sale_id'])->lockForUpdate()->first();if(!$s||$s->status!=='pending_payout'||$s->created_at>now()->subDays(7))abort(409,'Sale requires a seven-day hold.');$policy=DB::table('earning_policy')->where('id',1)->first();$bps=$v['kind']==='gift'?$policy->gift_creator_bps:$policy->content_creator_bps;if($bps===null)abort(409,'Configure creator revenue share first.');$source=$v['kind']==='gift'?$s->source_order:$s->order_id;if(!\App\Services\FundedCoins::sourceSafe($source)||DB::table('users')->where('id',$s->creator_id)->where(function($q){$q->where('qa_coin_mode',true)->orWhere('is_block',1);})->exists())abort(409,'Source funding or creator requires reconciliation.');DB::table($table)->where('id',$s->id)->update(['status'=>'available','net_minor'=>intdiv($s->gross_minor*$bps,10000),'creator_bps'=>$bps,'updated_at'=>now()]);return back()->with('success','Earnings released with the saved revenue share.');});}
 public function review(Request $r){$v=$r->validate(['id'=>'required|uuid','action'=>'required|in:approve,reject,paid','note'=>'required|string|max:500','payment_reference'=>'nullable|string|min:5|max:120']);return DB::transaction(function()use($v){$w=DB::table('earning_withdrawals')->where('id',$v['id'])->lockForUpdate()->first();if(!$w)abort(404);$next=['approve'=>'approved','reject'=>'rejected','paid'=>'paid'][$v['action']];if($w->status===$next)return back()->with('success','Already processed.');if(!in_array($w->status,['requested','approved'],true)||($next==='paid'&&$w->status!=='approved'))abort(409,'Invalid withdrawal transition.');if($next!=='rejected'&&(DB::table('users')->where('id',$w->user_id)->where(function($q){$q->where('is_block',1)->orWhere('qa_coin_mode',true);})->exists()||DB::table('earner_accounts')->where('user_id',$w->user_id)->value('status')!=='approved'))abort(409,'Earner is suspended or blocked.');$update=['status'=>$next,'review_note'=>$v['note'],'updated_at'=>now()];if($next==='paid'){if(!DB::table('earning_policy')->where('id',1)->value('withdrawals_enabled'))abort(409,'Payouts are paused.');foreach(DB::table('creator_sales')->where('withdrawal_id',$w->id)->get() as $sale)if(!\App\Services\FundedCoins::sourceSafe($sale->order_id))abort(409,'Sale funding requires reconciliation.');foreach(DB::table('gift_cash_earnings')->where('withdrawal_id',$w->id)->get() as $gift)if(!\App\Services\FundedCoins::sourceSafe($gift->source_order))abort(409,'Gift funding requires reconciliation.');if(DB::table('creator_sales')->where('withdrawal_id',$w->id)->whereIn('order_id',function($q){$q->select('id')->from('commerce_orders')->where('status','!=','settled')->orWhereIn('user_id',function($q){$q->select('user_id')->from('cash_wallets')->where('frozen',true);});})->exists())abort(409,'Funding requires reconciliation before payment.');if(empty($v['payment_reference']))abort(422,'External payment reference required.');$update['payment_reference']=$v['payment_reference'];$update['paid_at']=now();DB::table('creator_sales')->where('withdrawal_id',$w->id)->update(['status'=>'paid','updated_at'=>now()]);}if($next==='paid')DB::table('gift_cash_earnings')->where('withdrawal_id',$w->id)->update(['status'=>'paid','updated_at'=>now()]);if($next==='rejected')DB::table('gift_cash_earnings')->where('withdrawal_id',$w->id)->update(['status'=>'available','withdrawal_id'=>null,'updated_at'=>now()]);if($next==='rejected')DB::table('creator_sales')->where('withdrawal_id',$w->id)->update(['status'=>'available','withdrawal_id'=>null,'updated_at'=>now()]);DB::table('earning_withdrawals')->where('id',$w->id)->update($update);Earnings::event($w->id,$next,'admin:'.session('user_name'),$v['note']);Earnings::notify($w->user_id,'Your withdrawal is '.$next.'. '.$v['note']);return back()->with('success','Withdrawal '.$next.'. Approval does not send money.');});}
 public function destination(string $id){$w=DB::table('earning_withdrawals')->find($id);if(!$w)abort(404);return response(Crypt::decryptString($w->destination))->header('Content-Type','text/plain')->header('Cache-Control','no-store');}
}
